class KVStore {
  constructor() {
    this.store = {};
  }

  // 存储数据
  set(key, value) {
    const hash = this._hash(key);
    this.store[hash] = value;
  }

  // 根据键名获取数据
  get(key) {
    const hash = this._hash(key);
    return this.store[hash];
  }

  // 删除数据
  delete(key) {
    const hash = this._hash(key);
    delete this.store[hash];
  }

  // 检查数据是否存在
  has(key) {
    const hash = this._hash(key);
    return this.store.hasOwnProperty(hash);
  }

  // 计算哈希值
  _hash(key) {
    // 你可以在这里实现你自己的哈希函数
    return sha256(key);
  }
}
